{
  "unit_id": "p7",
  "status": "REVIEWED",
  "reason": "Inventory of explicit directives in p7, retaining parent/neighbor context (p6/p8) and unresolved cross-references.",
  "requirements": [
    {
      "local_id": "R7.1",
      "action": "check_and_disable_airplane_mode",
      "action_spans": [
        {"source_id": "p7", "quote": "Refer to the \"Understanding and Troubleshooting Your Phone's Cellular Service\" section for instructions on how to check and turn off Airplane Mode."}
      ],
      "scope": "user_phone",
      "source_spans": [
        {"source_id": "p7", "quote": "Airplane Mode is ON"}
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "AND",
        "label": "AirplaneMode_ON",
        "spans": [
          {"source_id": "p7", "quote": "Airplane Mode is ON"}
        ],
        "children": [
          {
            "op": "ATOM",
            "label": "mobile_data_unavailable",
            "spans": [
              {"source_id": "p7", "quote": "mobile data problems might occur"}
            ],
            "children": []
          }
        ]
      },
      "guard": null,
      "exceptions": [],
      "open_questions": [
        "What constitutes 'mobile data unavailable' in this context? (e.g., speed test failure, no connection, or other criteria?)"
      ]
    },
    {
      "local_id": "R7.2",
      "action": "enable_mobile_data",
      "action_spans": [
        {"source_id": "p7", "quote": "guide the user to use `toggle_data()` to turn mobile data ON."}
      ],
      "scope": "user_phone",
      "source_spans": [
        {"source_id": "p7", "quote": "Mobile Data is Turned OFF"}
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "ATOM",
        "label": "mobile_data_disabled",
        "spans": [
          {"source_id": "p7", "quote": "Mobile Data is Turned OFF"}
        ],
        "children": []
      },
      "guard": null,
      "exceptions": [],
      "open_questions": []
    },
    {
      "local_id": "R7.3",
      "action": "enable_data_roaming",
      "action_spans": [
        {"source_id": "p7", "quote": "guide them to use `toggle_roaming()` to ensure Data Roaming is ON."}
      ],
      "scope": "user_line",
      "source_spans": [
        {"source_id": "p7", "quote": "Roaming Issues (When User is Abroad)"}
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "AND",
        "label": "roaming_issue",
        "spans": [
          {"source_id": "p7", "quote": "Roaming Issues (When User is Abroad)"}
        ],
        "children": [
          {
            "op": "ATOM",
            "label": "user_abroad",
            "spans": [
              {"source_id": "p7", "quote": "When User is Abroad"}
            ],
            "children": []
          },
          {
            "op": "ATOM",
            "label": "mobile_data_unavailable",
            "spans": [
              {"source_id": "p7", "quote": "mobile data isn't working"}
            ],
            "children": []
          }
        ]
      },
      "guard": {
        "op": "AND",
        "label": "roaming_enabled_guard",
        "spans": [
          {"source_id": "p7", "quote": "check that the line associated with the phone number the user provided is roaming enabled"}
        ],
        "children": [
          {
            "op": "ATOM",
            "label": "line_roaming_enabled",
            "spans": [
              {"source_id": "p7", "quote": "the line is roaming enabled"}
            ],
            "children": []
          }
        ]
      },
      "exceptions": [],
      "open_questions": [
        "How is 'user abroad' verified programmatically? (e.g., via GPS, network detection, or user input?)",
        "What if the line is not roaming-enabled? (Escalation implied but not explicitly defined here.)"
      ]
    },
    {
      "local_id": "R7.4",
      "action": "disable_data_saver_mode",
      "action_spans": [
        {"source_id": "p8", "quote": "guide the user to use `toggle_data_saver_mode()` to turn it OFF."}
      ],
      "scope": "user_phone",
      "source_spans": [
        {"source_id": "p7", "quote": "Data Saver Mode is ON"}
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "ATOM",
        "label": "data_saver_active",
        "spans": [
          {"source_id": "p7", "quote": "Data Saver Mode is ON"}
        ],
        "children": []
      },
      "guard": null,
      "exceptions": [],
      "open_questions": []
    },
    {
      "local_id": "R7.5",
      "action": "disconnect_vpn",
      "action_spans": [
        {"source_id": "p8", "quote": "guide the user to use `disconnect_vpn()` to disconnect the VPN."}
      ],
      "scope": "user_phone",
      "source_spans": [
        {"source_id": "p7", "quote": "VPN Issues"}
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "AND",
        "label": "vpn_issue",
        "spans": [
          {"source_id": "p7", "quote": "VPN Issues"}
        ],
        "children": [
          {
            "op": "ATOM",
            "label": "vpn_connected",
            "spans": [
              {"source_id": "p8", "quote": "VPN is ON and connected"}
            ],
            "children": []
          },
          {
            "op": "ATOM",
            "label": "performance_poor",
            "spans": [
              {"source_id": "p8", "quote": "performance level is \"Poor\""}
            ],
            "children": []
          }
        ]
      },
      "guard": null,
      "exceptions": [],
      "open_questions": []
    },
    {
      "local_id": "R7.6",
      "action": "upgrade_data_plan",
      "action_spans": [
        {"source_id": "p8", "quote": "Change to a plan with more data."},
        {"source_id": "p8", "quote": "Add more data to the line by \"refueling\" data"}
      ],
      "scope": "user_line",
      "source_spans": [
        {"source_id": "p7", "quote": "Data Plan Limits Reached"}
      ],
      "modality": "PERMIT",
      "condition": {
        "op": "ATOM",
        "label": "data_limit_exceeded",
        "spans": [
          {"source_id": "p8", "quote": "data usage for a line associated with the phone number the user provided exceeds the plan's data limit"}
        ],
        "children": []
      },
      "guard": null,
      "exceptions": [],
      "open_questions": [
        "Are there restrictions on which plans can be upgraded to or how refueling is handled? (e.g., cost, availability?)"
      ]
    },
    {
      "local_id": "R7.7",
      "action": "upgrade_network_mode",
      "action_spans": [
        {"source_id": "p8", "quote": "guide the user to use `set_network_mode_preference(mode: str)` with the mode `\"4g_5g_preferred\"`"}
      ],
      "scope": "user_phone",
      "source_spans": [
        {"source_id": "p7", "quote": "Bad Network Preferences"}
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "OR",
        "label": "legacy_network_mode",
        "spans": [
          {"source_id": "p8", "quote": "Network mode preferences are the settings that determine the type of cellular network the phone will connect to."}
        ],
        "children": [
          {
            "op": "ATOM",
            "label": "network_mode_2g",
            "spans": [
              {"source_id": "p8", "quote": "shows \"2G\""}
            ],
            "children": []
          },
          {
            "op": "ATOM",
            "label": "network_mode_3g",
            "spans": [
              {"source_id": "p8", "quote": "shows \"3G\""}
            ],
            "children": []
          }
        ]
      },
      "guard": null,
      "exceptions": [],
      "open_questions": []
    },
    {
      "local_id": "R7.8",
      "action": "escalate_to_technical_support",
      "action_spans": [
        {"source_id": "p6", "quote": "**escalate to technical support for assistance with SIM security**."},
        {"source_id": "p6", "quote": "**escalate to technical support**."}
      ],
      "scope": "user_line",
      "source_spans": [
        {"source_id": "p6", "quote": "If the line is suspended and the agent can lift the suspension (per general policy), verify if service is restored."},
        {"source_id": "p6", "quote": "If the suspension cannot be lifted by the agent (e.g., due to contract end date as mentioned in general policy, or other reasons not resolvable by the agent)"}
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "OR",
        "label": "escalation_condition",
        "spans": [
          {"source_id": "p6", "quote": "escalate to technical support"}
        ],
        "children": [
          {
            "op": "ATOM",
            "label": "sim_locked",
            "spans": [
              {"source_id": "p6", "quote": "If it shows \"Locked\" (due to incorrect PIN or PUK entries)"}
            ],
            "children": []
          },
          {
            "op": "ATOM",
            "label": "suspension_unresolvable",
            "spans": [
              {"source_id": "p6", "quote": "the suspension cannot be lifted by the agent"}
            ],
            "children": []
          }
        ]
      },
      "guard": null,
      "exceptions": [],
      "open_questions": [
        "What specific criteria trigger escalation for SIM security vs. line suspension? Are there overlapping cases?"
      ]
    },
    {
      "local_id": "R7.9",
      "action": "verify_service_restoration",
      "action_spans": [
        {"source_id": "p6", "quote": "verify if service is restored."}
      ],
      "scope": "user_line",
      "source_spans": [
        {"source_id": "p6", "quote": "If the line is suspended and the agent can lift the suspension (per general policy)"}
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "AND",
        "label": "suspension_lifted",
        "spans": [
          {"source_id": "p6", "quote": "the line is suspended and the agent can lift the suspension"}
        ],
        "children": [
          {
            "op": "ATOM",
            "label": "suspension_lift_action",
            "spans": [
              {"source_id": "p6", "quote": "lift the suspension"}
            ],
            "children": []
          }
        ]
      },
      "guard": null,
      "exceptions": [],
      "open_questions": [
        "How is 'service restored' verified? (e.g., via `check_sim_status()`, `check_network_status()`, or user confirmation?)"
      ]
    },
    {
      "local_id": "R7.10",
      "action": "check_mobile_data_speed",
      "action_spans": [
        {"source_id": "p7", "quote": "`run_speed_test()` can be used to check for potential issues with mobile data."}
      ],
      "scope": "user_phone",
      "source_spans": [
        {"source_id": "p7", "quote": "Diagnosing Mobile Data Issues"}
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "ATOM",
        "label": "mobile_data_unavailable_or_slow",
        "spans": [
          {"source_id": "p7", "quote": "mobile data problems might occur"}
        ],
        "children": []
      },
      "guard": null,
      "exceptions": [],
      "open_questions": [
        "What threshold defines 'slow' mobile data? (e.g., speed test result below 'Excellent')"
      ]
    },
    {
      "local_id": "R7.11",
      "action": "reset_apn_settings",
      "action_spans": [
        {"source_id": "p6", "quote": "guide the user to use `reset_apn_settings()` to reset the APN settings."}
      ],
      "scope": "user_phone",
      "source_spans": [
        {"source_id": "p6", "quote": "Incorrect APN Settings"}
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "ATOM",
        "label": "apn_incorrect",
        "spans": [
          {"source_id": "p6", "quote": "If `check_apn_settings()` shows \"Incorrect\""}
        ],
        "children": []
      },
      "guard": {
        "op": "ATOM",
        "label": "reboot_required",
        "spans": [
          {"source_id": "p6", "quote": "After resetting the APN settings, the user must be instructed to use `reboot_device()` for the changes to apply."}
        ],
        "children": []
      },
      "exceptions": [],
      "open_questions": []
    },
    {
      "local_id": "R7.12",
      "action": "reseat_sim_card",
      "action_spans": [
        {"source_id": "p6", "quote": "guide the user to use `reseat_sim_card()` to ensure the SIM card is correctly inserted."}
      ],
      "scope": "user_phone",
      "source_spans": [
        {"source_id": "p6", "quote": "The SIM card is not properly seated"}
      ],
      "modality": "REQUIRE",
      "condition": {
        "op": "ATOM",
        "label": "sim_missing_or_improperly_seated",
        "spans": [
          {"source_id": "p6", "quote": "If it shows \"Missing\""}
        ],
        "children": []
      },
      "guard": null,
      "exceptions": [],
      "open_questions": []
    }
  ]
}
